{
  "name": "@brianluby/agent-brain",
  "version": "1.1.2",
  "description": "Give Claude Code photographic memory in ONE portable file",
  "type": "module",
  "main": "dist/opencode/plugin.js",
  "types": "dist/opencode/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/opencode/plugin.d.ts",
      "default": "./dist/opencode/plugin.js"
    },
    "./mind": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./opencode": {
      "types": "./dist/opencode/plugin.d.ts",
      "default": "./dist/opencode/plugin.js"
    }
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "tool.execute.after",
      "event"
    ]
  },
  "scripts": {
    "build": "tsup && cp src/hooks/hooks.json dist/hooks/",
    "dev": "tsup --watch",
    "lint": "eslint src/",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "npm run build"
  },
  "files": [
    "dist",
    "skills",
    "commands",
    ".claude-plugin"
  ],
  "keywords": [
    "claude",
    "claude-code",
    "claude-code-plugin",
    "anthropic",
    "opencode",
    "opencode-plugin",
    "memory",
    "ai-memory",
    "context-persistence",
    "agent-brain",
    "portable-memory",
    "persistent-memory",
    "llm-memory",
    "ai-assistant"
  ],
  "author": "Brian Luby",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/brianluby/Agent-brain.git"
  },
  "homepage": "https://github.com/brianluby/agent-brain",
  "bugs": {
    "url": "https://github.com/brianluby/Agent-brain/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.10",
    "@memvid/sdk": "^2.0.149",
    "proper-lockfile": "^4.1.2"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.2",
    "@types/node": "^22.0.0",
    "@types/proper-lockfile": "^4.1.4",
    "eslint": "^9.0.0",
    "tsup": "^8.0.0",
    "typescript": "^5.7.0",
    "typescript-eslint": "^8.50.0",
    "vitest": "^3.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
